-- Generated by medallion from spec/tables/gold_payments_by_method_daily.toml. Do not edit by hand.
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.gold.payments_by_method_daily (
  paid_date DATE COMMENT 'Day the payment settled (UTC)',
  method STRING COMMENT 'Payment method',
  payments_count BIGINT COMMENT 'Settled payments',
  paid_amount DECIMAL(18,2) COMMENT 'Sum of settled payment amounts'
)
COMMENT 'Settled payment count and value by day and payment method, for treasury and reconciliation.'
TBLPROPERTIES (
  'governance.owner' = 'finance-data',
  'governance.domain' = 'finance',
  'governance.classification' = 'internal',
  'governance.spec' = 'spec/tables/gold_payments_by_method_daily.toml',
  'governance.grain' = 'paid_date, method'
)
AS SELECT
  CAST(to_date(p.paid_at) AS DATE) AS paid_date,
  CAST(p.method AS STRING) AS method,
  CAST(count(*) AS BIGINT) AS payments_count,
  CAST(sum(p.amount) AS DECIMAL(18,2)) AS paid_amount
FROM ${catalog}.silver.payments AS p
GROUP BY to_date(p.paid_at), p.method;
